Request: Write isEven(value), returning true only for even integers. Return false for non-integers or non-number inputs.
Answer:
function isEven(value) {
  return Number.isInteger(value) && value % 2 === 0;
}

Request: Write isOdd(value), returning true only for odd integers, including negative odd integers. Return false for other inputs.
Answer:
function isOdd(value) {
  return Number.isInteger(value) && Math.abs(value % 2) === 1;
}

Request: Write rectanglePerimeter(width, height). Return twice the sum of the sides for finite nonnegative numbers; otherwise return null.
Answer:
function rectanglePerimeter(width, height) {
  if (!Number.isFinite(width) || !Number.isFinite(height) || width < 0 || height < 0) return null;
  return 2 * (width + height);
}

Request: Write rectangleArea(width, height). Return their product for finite nonnegative numbers; otherwise return null.
Answer:
function rectangleArea(width, height) {
  if (!Number.isFinite(width) || !Number.isFinite(height) || width < 0 || height < 0) return null;
  return width * height;
}

Request: Write toFahrenheit(celsius), converting a finite Celsius number to Fahrenheit. Return null for non-number or non-finite input.
Answer:
function toFahrenheit(celsius) {
  if (!Number.isFinite(celsius)) return null;
  return celsius * 9 / 5 + 32;
}

Request: Write toCelsius(fahrenheit), converting a finite Fahrenheit number to Celsius. Return null for non-number or non-finite input.
Answer:
function toCelsius(fahrenheit) {
  if (!Number.isFinite(fahrenheit)) return null;
  return (fahrenheit - 32) * 5 / 9;
}

